<script setup lang="ts">
import AppDialog from './AppDialog.vue';
import {ApiError} from '../services/api';
import {computed,onBeforeUnmount,ref,watch} from 'vue';
const props=defineProps<{id:number;canEdit:boolean;request:<T>(path:string,method?:string,body?:unknown)=>Promise<T>;download:(path:string)=>Promise<{blob:Blob;type:string}>}>();
type Document={numero_registro:string;tipo:string;vigencia:string;status:string;motivo:string;origem:string;responsavel:string|null;justificativa:string|null;versao:string;desatualizado:boolean;arquivo_disponivel:boolean;atualizado_em:string;incluir_envio:boolean;historico:boolean};
const rows=ref<Document[]>([]),query=ref(''),status=ref(''),loading=ref(false),busy=ref(''),error=ref(''),failed=ref(false);let alive=true,generation=0;
const decision=ref<Document|null>(null),action=ref<'confirmado'|'rejeitado'>('confirmado'),reason=ref(''),saving=ref(false),conflict=ref(false),formError=ref(''),notice=ref('');
const mode=ref<'aplicabilidade'|'participacao'>('aplicabilidade'),include=ref(false);
const canSave=computed(()=>!!decision.value&&!decision.value.desatualizado&&!conflict.value&&!saving.value&&!!reason.value.trim()&&(mode.value==='participacao'||action.value==='rejeitado'||decision.value.arquivo_disponivel));
function openDecision(row:Document){if(!props.canEdit||busy.value||loading.value)return;mode.value='aplicabilidade';decision.value=row;action.value=row.status==='rejeitado'?'rejeitado':'confirmado';reason.value='';formError.value='';conflict.value=row.desatualizado;notice.value='';}
function openParticipation(row:Document){openDecision(row);if(decision.value){mode.value='participacao';include.value=row.incluir_envio;}}
async function decide(){if(!props.canEdit||!canSave.value||!decision.value)return;const current=generation;saving.value=true;formError.value='';try{const payload={numero:decision.value.numero_registro,justificativa:reason.value.trim(),versao:decision.value.versao,...(mode.value==='participacao'?{incluir_envio:include.value}:{status:action.value})};const data=await props.request<Document[]>('/api/contexto/clientes/'+props.id+'/documentos/'+(mode.value==='participacao'?'participacao':'decidir'),'POST',payload);if(!alive||current!==generation)return;rows.value=data;decision.value=null;notice.value=mode.value==='participacao'?'Participação no envio registrada.':'Decisão de aplicabilidade registrada.';}catch(cause){if(alive&&current===generation){formError.value=(cause as Error).message;if(cause instanceof ApiError&&cause.status===409)conflict.value=true;}}finally{if(alive&&current===generation)saving.value=false;}}
async function refreshDecision(){if(!props.canEdit||saving.value)return;const current=generation;saving.value=true;formError.value='';try{const data=await props.request<Document[]>('/api/contexto/clientes/'+props.id+'/documentos/atualizar','POST',{});if(!alive||current!==generation)return;rows.value=data;decision.value=null;notice.value='Aplicabilidade atualizada. Abra o documento e confira novamente antes de decidir.';}catch(cause){if(alive&&current===generation)formError.value=(cause as Error).message;}finally{if(alive&&current===generation)saving.value=false;}}
const normalize=(value:string)=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim();
const visible=computed(()=>rows.value.filter(row=>(!status.value||row.status===status.value)&&normalize([row.numero_registro,row.tipo,row.vigencia,row.motivo,row.responsavel,row.justificativa].join(' ')).includes(normalize(query.value))));
const labels:Record<string,string>={candidato:'Candidato',confirmado:'Confirmado',rejeitado:'Rejeitado'};
async function load(){const current=++generation;rows.value=[];error.value='';notice.value='';failed.value=false;loading.value=true;try{const data=await props.request<Document[]>('/api/contexto/clientes/'+props.id+'/documentos');if(alive&&current===generation)rows.value=data;}catch(cause){if(alive&&current===generation){failed.value=true;error.value=(cause as Error).message;}}finally{if(alive&&current===generation)loading.value=false;}}
async function original(row:Document){if(busy.value||!row.arquivo_disponivel)return;const current=generation;busy.value=row.numero_registro;error.value='';try{const file=await props.download('/api/contexto/clientes/'+props.id+'/documentos/original?numero='+encodeURIComponent(row.numero_registro));if(!alive||current!==generation)return;const url=URL.createObjectURL(file.blob),link=document.createElement('a');link.href=url;link.download=row.numero_registro.replace(/[^A-Z0-9_-]/gi,'_')+(file.type.includes('pdf')?'.pdf':'.doc');link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive&&current===generation)busy.value='';}}
watch(()=>props.id,()=>{query.value='';status.value='';busy.value='';decision.value=null;saving.value=false;void load();},{immediate:true});onBeforeUnmount(()=>{alive=false;generation++;});
</script>
<template><section class="client-documents" aria-label="Documentos da empresa"><header class="document-panel-heading"><div><h3>Documentos da empresa</h3><p>Confira a aplicabilidade e o original de cada instrumento relacionado a este cliente.</p></div><button type="button" class="secondary" :disabled="loading||!!busy" @click="load">Recarregar documentos</button></header>
<div class="registry-controls"><label>Buscar documento do cliente<input v-model="query" type="search"></label><label>Aplicabilidade<select v-model="status"><option value="">Todas</option><option v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</option></select></label><button type="button" class="secondary" @click="query='';status=''">Limpar filtros</button></div>
<p v-if="notice" role="status">{{ notice }}</p><p v-if="loading" role="status">Carregando documentos do cliente…</p><p v-if="error" role="alert">{{ error }}</p><p v-if="!loading&&!failed" role="status">{{ visible.length }} de {{ rows.length }} documentos</p>
<div v-if="!loading&&!failed" class="registry-scroll"><table><caption>Aplicabilidade dos documentos do cliente</caption><thead><tr><th scope="col">Instrumento</th><th scope="col">Aplicabilidade</th><th scope="col">Conferência e versão</th><th scope="col">Participação no envio</th><th scope="col">Original e decisão</th></tr></thead><tbody><tr v-for="row in visible" :key="row.numero_registro"><td><strong>{{ row.numero_registro }}</strong><p>{{ row.tipo||'Tipo não informado' }}</p><p>{{ row.vigencia||'Vigência não informada' }}</p></td><td><span class="status-badge" :data-tone="row.status==='confirmado'?'success':'neutral'">{{ labels[row.status]||row.status }}</span><p>{{ row.motivo||'Motivo não informado' }}</p><p v-if="row.desatualizado" class="consolidation-warning">Conferência desatualizada. Confira novamente a aplicabilidade.</p></td><td><p>{{ row.origem==='manual'?'Decisão manual':'Regra automática' }}</p><p v-if="row.responsavel">Responsável: {{ row.responsavel }}</p><p v-if="row.justificativa">{{ row.justificativa }}</p><details><summary>Versão atual e data</summary><p class="publication-version">{{ row.versao }}</p><p>{{ new Date(row.atualizado_em).toLocaleString('pt-BR') }}</p></details></td><td><p>{{ row.incluir_envio?'Participa das próximas preparações':'Fora das próximas preparações' }}</p><p v-if="row.historico">Anterior ao cadastro do cliente</p><button v-if="canEdit" type="button" class="secondary" :disabled="!!busy||saving" :aria-label="'Alterar participação de '+row.numero_registro" @click="openParticipation(row)">Alterar participação</button></td><td><button v-if="row.arquivo_disponivel" type="button" class="secondary" :disabled="!!busy" :aria-label="'Baixar original de '+row.numero_registro" @click="original(row)">{{ busy===row.numero_registro?'Baixando…':'Baixar original' }}</button><span v-else>Original não disponível</span><p v-if="canEdit"><button type="button" class="secondary" :disabled="!!busy||saving" :aria-label="'Decidir aplicabilidade de '+row.numero_registro" @click="openDecision(row)">Decidir aplicabilidade</button></p></td></tr><tr v-if="!visible.length"><td colspan="5">{{ rows.length?'Nenhum documento corresponde aos filtros.':'Nenhum documento relacionado a este cliente.' }}</td></tr></tbody></table></div></section>
<AppDialog v-if="decision" :title="mode==='participacao'?'Participação no envio':'Decidir aplicabilidade'" :busy="saving" @close="decision=null"><h3>{{ decision.numero_registro }}</h3><p>{{ decision.tipo }} · {{ decision.vigencia||'Vigência não informada' }}</p><p>Situação consultada: {{ labels[decision.status]||decision.status }}. {{ decision.motivo }}</p><details><summary>Versão conferida</summary><p class="publication-version">{{ decision.versao }}</p></details><p>O responsável será registrado com o nome e a identidade da sua sessão.</p><form class="vue-form" @submit.prevent="decide"><label v-if="mode==='aplicabilidade'">Decisão de aplicabilidade<select v-model="action" :disabled="saving||conflict"><option value="confirmado">Confirmar aplicabilidade</option><option value="rejeitado">Rejeitar aplicabilidade</option></select></label><template v-if="mode==='participacao'"><p>A participação controla as próximas preparações. A aplicabilidade precisa estar confirmada e as regras de destinatários e aprovação continuam valendo.</p><p>Envios já preparados devem ser geridos na fila. Esta ação não prepara nem aprova e-mails.</p><label class="confirmation-check"><input v-model="include" type="checkbox" :disabled="saving||conflict">Participar das próximas preparações</label></template><label>{{ mode==='participacao'?'Justificativa da participação':'Justificativa da aplicabilidade' }}<textarea v-model="reason" required maxlength="2000" :disabled="saving||conflict" /></label><p v-if="mode==='aplicabilidade'&&action==='confirmado'&&!decision.arquivo_disponivel">Original indisponível. É necessário um original íntegro para confirmar a aplicabilidade.</p><p v-if="formError" role="alert">{{ formError }}</p><div v-if="conflict" class="consolidation-warning"><p>Documento, vínculos ou decisão precisam de nova conferência. O rascunho está preservado e o envio bloqueado.</p><p>Atualizar fecha este rascunho. Reabra o documento para conferir a situação e registrar uma nova decisão.</p><button type="button" class="secondary" :disabled="saving" @click="refreshDecision">Atualizar e conferir novamente</button></div><footer><button type="button" class="secondary" :disabled="saving" @click="decision=null">Cancelar</button><button type="submit" class="primary" :disabled="!canSave">{{ mode==='participacao'?'Registrar participação':'Registrar aplicabilidade' }}</button></footer></form></AppDialog></template>
